import{_ as t}from"./chunks/22.DPtKHQKO.js";import{_ as o,a,b as r,c as i}from"./chunks/26.BBZ9PsJf.js";import{_ as s,o as n,c as l,a0 as h}from"./chunks/framework.DRjqbEpm.js";const y=JSON.parse('{"title":"❤️ Bookmark Vault & Hover Panel","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/bookmark-vault.md","filePath":"en/guide/bookmark-vault.md"}'),d={name:"en/guide/bookmark-vault.md"};function c(u,e,p,k,m,g){return n(),l("div",null,[...e[0]||(e[0]=[h('<h1 id="❤️-bookmark-vault-hover-panel" tabindex="-1">❤️ Bookmark Vault &amp; Hover Panel <a class="header-anchor" href="#❤️-bookmark-vault-hover-panel" aria-label="Permalink to &quot;❤️ Bookmark Vault &amp; Hover Panel&quot;">​</a></h1><blockquote><p>PRO Feature: Move your mouse over a video to open the control panel. Keep your favorite videos organized!</p></blockquote><hr><h2 id="_1-the-hover-panel-🎯" tabindex="-1">1. The Hover Panel 🎯 <a class="header-anchor" href="#_1-the-hover-panel-🎯" aria-label="Permalink to &quot;1. The Hover Panel 🎯&quot;">​</a></h2><p>The <strong>Hover Panel</strong> is a great feature in V-Train PRO. When you are on a <strong>video playback page</strong>, a small panel appears after you wait a tiny bit (150 milliseconds).</p><div class="info custom-block"><p class="custom-block-title">📍 It does not appear on small pictures</p><p>The panel only appears on the page where you watch the video. It does not appear when you hover over a small picture in a video list.</p></div><blockquote><p><img src="'+t+'" alt="Floating Interaction Panel"></p></blockquote><p>The panel has these buttons:</p><table tabindex="0"><thead><tr><th>Button</th><th>Function</th></tr></thead><tbody><tr><td><strong>Like</strong> 👍</td><td>Rate this video as good</td></tr><tr><td><strong>Dislike</strong> 👎</td><td>Rate this video as bad</td></tr><tr><td><strong>Bookmark</strong> ❤️</td><td>Save the video to a folder</td></tr><tr><td><strong>Screenshot</strong> 📸</td><td>Take a picture to use as the cover</td></tr><tr><td><strong>Open Vault</strong> 📚</td><td>Open your Bookmark Vault</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Move the panel!</p><p>You can click and drag the panel to anywhere on the screen. V-Train will remember where you put it.</p></div><div class="info custom-block"><p class="custom-block-title">PRO Feature</p><p>The Hover Panel and the Bookmark Vault are <strong>V-Train PRO</strong> features. If you use the Free version, you must upgrade to use them.</p></div><hr><h2 id="_2-rating-videos-👍-like-👎-dislike-⭐" tabindex="-1">2. Rating Videos (👍 Like / 👎 Dislike) ⭐ <a class="header-anchor" href="#_2-rating-videos-👍-like-👎-dislike-⭐" aria-label="Permalink to &quot;2. Rating Videos (👍 Like / 👎 Dislike) ⭐&quot;">​</a></h2><h3 id="what-is-rating" tabindex="-1">What is rating? <a class="header-anchor" href="#what-is-rating" aria-label="Permalink to &quot;What is rating?&quot;">​</a></h3><p>Rating lets you quickly mark if you liked a video or not.</p><h3 id="how-to-rate-a-video" tabindex="-1">How to rate a video? <a class="header-anchor" href="#how-to-rate-a-video" aria-label="Permalink to &quot;How to rate a video?&quot;">​</a></h3><ol><li>Move your mouse over the video to open the panel.</li><li>Click <strong>👍</strong> for good, or click <strong>👎</strong> for bad.</li><li>Your rating is saved immediately.</li></ol><h3 id="seeing-your-ratings" tabindex="-1">Seeing Your Ratings <a class="header-anchor" href="#seeing-your-ratings" aria-label="Permalink to &quot;Seeing Your Ratings&quot;">​</a></h3><p>After you rate a video, a <strong>small badge</strong> will appear on the video&#39;s picture:</p><ul><li>👍 Thumbs up → You liked it</li><li>👎 Thumbs down → You did not like it</li></ul><blockquote><p><img src="'+o+'" alt="Rating Badge Diagram"></p></blockquote><p>This helps you see what you already watched and liked.</p><div class="tip custom-block"><p class="custom-block-title">Change your mind?</p><p>Click the same button again to remove the rating. Click the other button to change your rating.</p></div><hr><h2 id="_3-save-to-bookmark-vault-❤️-📁" tabindex="-1">3. Save to Bookmark Vault (❤️) 📁 <a class="header-anchor" href="#_3-save-to-bookmark-vault-❤️-📁" aria-label="Permalink to &quot;3. Save to Bookmark Vault (❤️) 📁&quot;">​</a></h2><h3 id="how-to-save-a-video" tabindex="-1">How to save a video <a class="header-anchor" href="#how-to-save-a-video" aria-label="Permalink to &quot;How to save a video&quot;">​</a></h3><ol><li>On a video <strong>playback page</strong>, click <strong>❤️</strong> on the panel.</li><li>A list of your folders will open.</li><li>Click a folder to save it there.</li><li>Done!</li></ol><div class="info custom-block"><p class="custom-block-title">Note</p><p>You can only save a video from the playback page.</p></div><blockquote><p><img src="'+a+'" alt="Folder Picker Diagram"></p></blockquote><hr><h2 id="_4-screenshot-cover-feature-📸-🖼️" tabindex="-1">4. Screenshot Cover Feature (📸) 🖼️ <a class="header-anchor" href="#_4-screenshot-cover-feature-📸-🖼️" aria-label="Permalink to &quot;4. Screenshot Cover Feature (📸) 🖼️&quot;">​</a></h2><h3 id="what-is-a-screenshot-cover" tabindex="-1">What is a Screenshot Cover? <a class="header-anchor" href="#what-is-a-screenshot-cover" aria-label="Permalink to &quot;What is a Screenshot Cover?&quot;">​</a></h3><p>When you click the 📸 button, V-Train takes a picture of the video. It uses this picture as the cover in your Bookmark Vault.</p><p>Why do we need this? Many websites stop showing covers after a few days. Taking a picture saves the cover forever.</p><h3 id="technical-flow-of-screenshot" tabindex="-1">Technical Flow of Screenshot <a class="header-anchor" href="#technical-flow-of-screenshot" aria-label="Permalink to &quot;Technical Flow of Screenshot&quot;">​</a></h3><p>V-Train captures the cover using the following flow:</p><ol><li><strong>Prioritize Canvas/Video Capture</strong>: Attempts to take a canvas screenshot directly from the video element on the page.</li><li><strong>Fallback to OG Image</strong>: If the first step fails, it tries to fetch the official sharing image from the page&#39;s <code>&lt;meta property=&quot;og:image&quot;&gt;</code> tag.</li><li><strong>Fallback Screenshot via Context Menu</strong>: Due to strict cross-origin ad interference or CORS policies on certain sites, the 1-click snapshot might fail and display a red &quot;❌&quot;. When this happens, a red tooltip will pop up. Simply follow its instruction: right-click the page and select &quot;📸 V-Train: Force Physical Snapshot&quot;. The system will temporarily request the <code>activeTab</code> permission to bypass all restrictions and force the screenshot capture.</li><li><strong>Compression</strong>: The captured image is compressed into a <strong>320px wide WebP format</strong> to balance image quality and storage space.</li><li><strong>Save to IndexedDB</strong>: The compressed image is securely saved to your browser&#39;s local IndexedDB database (<code>vt_thumbnails</code> store).</li></ol><div class="tip custom-block"><p class="custom-block-title">Where are the pictures saved?</p><p>The pictures are saved on <strong>your computer only</strong>. They are not uploaded to the internet. They will not sync to your other computers.</p></div><blockquote><p><img src="'+r+'" alt="Screenshot Capture and WebP Compression Diagram"></p></blockquote><hr><h2 id="_5-bookmark-vault-screen-📚" tabindex="-1">5. Bookmark Vault Screen 📚 <a class="header-anchor" href="#_5-bookmark-vault-screen-📚" aria-label="Permalink to &quot;5. Bookmark Vault Screen 📚&quot;">​</a></h2><h3 id="how-to-open-the-bookmark-vault" tabindex="-1">How to open the Bookmark Vault? <a class="header-anchor" href="#how-to-open-the-bookmark-vault" aria-label="Permalink to &quot;How to open the Bookmark Vault?&quot;">​</a></h3><ol><li><strong>From the Hover Panel</strong>: Click the 📚 button.</li><li><strong>From the V-Train Menu</strong>: Click the VT icon in Chrome, then click &quot;Bookmark Vault&quot;.</li></ol><blockquote><p><img src="'+i+`" alt="Bookmark Vault Main Interface Diagram"></p></blockquote><h3 id="what-can-you-do-here" tabindex="-1">What can you do here? <a class="header-anchor" href="#what-can-you-do-here" aria-label="Permalink to &quot;What can you do here?&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>Description</th></tr></thead><tbody><tr><td><strong>Grid View</strong></td><td>Show large pictures</td></tr><tr><td><strong>List View</strong></td><td>Show small pictures and more text</td></tr><tr><td><strong>Sort</strong></td><td>Sort by newest, oldest, or name</td></tr><tr><td><strong>Search</strong></td><td>Find a video by typing its name</td></tr><tr><td><strong>Folders</strong></td><td>See your folders on the left</td></tr><tr><td><strong>Pages</strong></td><td>Show 12 videos per page</td></tr></tbody></table><hr><h2 id="_6-using-folders-📂" tabindex="-1">6. Using Folders 📂 <a class="header-anchor" href="#_6-using-folders-📂" aria-label="Permalink to &quot;6. Using Folders 📂&quot;">​</a></h2><h3 id="create-a-folder" tabindex="-1">Create a Folder <a class="header-anchor" href="#create-a-folder" aria-label="Permalink to &quot;Create a Folder&quot;">​</a></h3><p>Click the &quot;New Folder&quot; button on the left. You can create folders inside other folders. For example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>📁 Music</span></span>
<span class="line"><span>  📁 Pop</span></span>
<span class="line"><span>  📁 Rock</span></span>
<span class="line"><span>📁 Tutorials</span></span>
<span class="line"><span>  📁 Cooking</span></span></code></pre></div><h3 id="manage-folders" tabindex="-1">Manage Folders <a class="header-anchor" href="#manage-folders" aria-label="Permalink to &quot;Manage Folders&quot;">​</a></h3><p><strong>Right-click</strong> on any folder to:</p><ul><li>✏️ <strong>Rename</strong>: Change the folder&#39;s name.</li><li>🗑️ <strong>Delete</strong>: Delete the folder and all videos inside it.</li></ul><div class="warning custom-block"><p class="custom-block-title">Be careful!</p><p>If you delete a folder, it is gone forever. You cannot get it back.</p></div><h3 id="move-videos" tabindex="-1">Move Videos <a class="header-anchor" href="#move-videos" aria-label="Permalink to &quot;Move Videos&quot;">​</a></h3><p>There are three buttons on each video card:</p><table tabindex="0"><thead><tr><th>Button</th><th>Function</th></tr></thead><tbody><tr><td>🗑️ Delete</td><td>Delete this video (cannot get it back)</td></tr><tr><td>📂 Move to</td><td>Move this video to a different folder</td></tr><tr><td>✏️ Rename</td><td>Change the video&#39;s name</td></tr></tbody></table><hr><h2 id="_7-find-your-videos-🔍" tabindex="-1">7. Find Your Videos 🔍 <a class="header-anchor" href="#_7-find-your-videos-🔍" aria-label="Permalink to &quot;7. Find Your Videos 🔍&quot;">​</a></h2><h3 id="sort-videos" tabindex="-1">Sort Videos <a class="header-anchor" href="#sort-videos" aria-label="Permalink to &quot;Sort Videos&quot;">​</a></h3><p>Click the sort menu in the top right corner:</p><ul><li><strong>Newest</strong>: Show the newest videos first.</li><li><strong>Oldest</strong>: Show the oldest videos first.</li><li><strong>Title A→Z</strong>: Show videos in alphabetical order.</li></ul><h3 id="search-for-a-video" tabindex="-1">Search for a Video <a class="header-anchor" href="#search-for-a-video" aria-label="Permalink to &quot;Search for a Video&quot;">​</a></h3><p>Type a word in the search box at the top. The system will find videos with that word in the title. It searches the current folder and all folders inside it.</p><hr><h2 id="_8-anti-hotlinking-protection-🔒" tabindex="-1">8. Anti-Hotlinking Protection 🔒 <a class="header-anchor" href="#_8-anti-hotlinking-protection-🔒" aria-label="Permalink to &quot;8. Anti-Hotlinking Protection 🔒&quot;">​</a></h2><h3 id="what-is-this" tabindex="-1">What is this? <a class="header-anchor" href="#what-is-this" aria-label="Permalink to &quot;What is this?&quot;">​</a></h3><p>Many websites block you from showing their pictures on other pages. This causes broken pictures in your Bookmark Vault.</p><h3 id="how-v-train-fixes-it" tabindex="-1">How V-Train fixes it <a class="header-anchor" href="#how-v-train-fixes-it" aria-label="Permalink to &quot;How V-Train fixes it&quot;">​</a></h3><p>V-Train has a special tool that tricks those websites. It makes them think you are on their own page. This allows the pictures to load normally.</p><div class="info custom-block"><p class="custom-block-title">🛡️ Is this safe?</p><p>Yes, it is 100% safe. It only works for pictures and does not share your private data.</p></div><hr><h2 id="_9-live-sync-across-tabs-🔄" tabindex="-1">9. Live Sync Across Tabs 🔄 <a class="header-anchor" href="#_9-live-sync-across-tabs-🔄" aria-label="Permalink to &quot;9. Live Sync Across Tabs 🔄&quot;">​</a></h2><p>If you have many Bookmark Vault pages open, they will all update at the same time!</p><p>If you add a video in Tab A, it will appear in Tab B immediately. You do not need to refresh the page.</p><div class="info custom-block"><p class="custom-block-title">Note</p><p>This only works on the same computer. It does not sync to your phone or another computer.</p></div><hr><h2 id="_10-free-version-bookmarks-are-never-deleted-🛡️" tabindex="-1">10. Free Version: Bookmarks are Never Deleted 🛡️ <a class="header-anchor" href="#_10-free-version-bookmarks-are-never-deleted-🛡️" aria-label="Permalink to &quot;10. Free Version: Bookmarks are Never Deleted 🛡️&quot;">​</a></h2><p>V-Train automatically deletes very old video records to save space.</p><p><strong>But V-Train will NEVER delete a video if you put it in the Bookmark Vault.</strong></p><p>Even if you use the Free version, your saved videos are safe forever.</p><hr><h2 id="tip-how-to-use-the-bookmark-vault-well-🗂️" tabindex="-1">Tip: How to use the Bookmark Vault well 🗂️ <a class="header-anchor" href="#tip-how-to-use-the-bookmark-vault-well-🗂️" aria-label="Permalink to &quot;Tip: How to use the Bookmark Vault well 🗂️&quot;">​</a></h2><ol><li><strong>Use the panel to rate</strong>: If you like a video, click 👍.</li><li><strong>Use ❤️ to save</strong>: Put the video in a folder so you can find it later.</li><li><strong>Use 📸 to take a picture</strong>: If you think the cover picture might disappear later, take a picture of it.</li><li><strong>Clean your folders</strong>: Move videos to the correct folders.</li><li><strong>Search</strong>: If you cannot find a video, use the search box!</li></ol>`,85)])])}const w=s(d,[["render",c]]);export{y as __pageData,w as default};
